import { Component, Event, EventEmitter, h, Element } from "@stencil/core";

/**
 * @since 0.1.64
 * @status stable
 *
 * @slot menu - Main menu nav.
 * @slot logo-name - Company's logo and Product Name.
 * @slot search - Search input-field to perform global search.
 * @slot utilities - Set of element to display utilities for user. Normally contain icons and dropdowns.
 * @slot user-profile - Set of element to display user profile.
 * @slot application-launcher - Application Launcher
 * @slot skip - Skip navigation links for accessibility (since version 2.18.24).
 *
 * @event hbr-height-changed - Emitted when height of the header changes due to focus entering or leaving the skip slot.
 */

@Component({
	tag: "hbr-shell-header",
	styleUrl: "header.scss",
	shadow: true,
})
export class Header {
	private skipLinksRef?: HTMLDivElement;
	@Element() host: HTMLHbrShellHeaderElement;
	private previousHeight: number = 0;

	/** Emitted when height of the header changes due to focus entering or leaving the skip slot. */
	@Event({ eventName: "hbr-height-changed" }) heightChange: EventEmitter<{ height: number }>;

	emitHeightChange = () => {
			const {height} = this.host.getBoundingClientRect()
			if (this.previousHeight !== height) {
				this.heightChange.emit({height});
			}
			this.previousHeight = height;
	}

	private handleSkipLinksFocusIn = () => {
		if (this.skipLinksRef?.matches(':focus-within')) {
			this.emitHeightChange()
		}
	};

	private handleSkipLinksFocusOut = () => {
		if (!this.skipLinksRef?.matches(':focus-within')) {
			this.emitHeightChange()
		}
	};

	render() {
		return (
			<div
				class="wrapper"
				part="wrapper"
				onFocusin={this.handleSkipLinksFocusIn}
				onFocusout={this.handleSkipLinksFocusOut}
			>
				<div
					class="skip"
					part="skip"
					ref={(el) => (this.skipLinksRef = el)}
				>
					<slot name="skip"></slot>
				</div>
				<header class={{ "shell-header__main": true }} part="base">
					<slot name="menu" />
					<slot name="logo-name" />
					<slot name="title" />
					<slot name="search" />
					<slot name="utilities" />
					<slot name="user-profile" />
					<slot name="application-launcher" />
				</header>
			</div>
		);
	}
}
